export function findCreatureToken({ query = "", category = "", traits = [] } = {}) {
  const q = String(query || "").trim().toLowerCase();
  const wantCat = String(category || "").trim();
  const wantTraits = Array.isArray(traits) ? traits : [];
  let best = null;
  let bestScore = 0;
  for (const tk of CREATURE_TOKENS_CATALOG) {
    let score = 0;
    if (wantCat && tk.category === wantCat) score += 4;
    if (q) {
      const hay = `${tk.id} ${tk.name} ${tk.category} ${(tk.traits || []).join(" ")}`.toLowerCase();
      if (tk.id.toLowerCase() === q || tk.name.toLowerCase() === q) score += 20;
      else if (hay.includes(q)) score += 10;
    }
    for (const tr of wantTraits) {
      if ((tk.traits || []).includes(tr)) score += 3;
    }
    if (score > bestScore) {
      bestScore = score;
      best = tk;
    }
  }
  return best;
}
